{
  "comparisons": [
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "ROS generation",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00040",
          "quote": "ROS were measured with the non-fluorescent probe 2', 7'-dichlorofluorescein diacetate (DCFH-DA) (Beyotime Company, China) according to a previous study [22, 23]. Briefly, after the cells were treated with RF-EMFs (1, 2, or 4 W/kg) for 24 h, the culture medium was removed and the cells were washed three times with PBS. The cells were then exposed to 10 mM DCFH-DA for 20 min, washed, and then scraped into 1 ml of PBS. The fluorescence was read at 495 nm for excitation and 535 nm for emission with a microplate reader (Enspire, PerkinElmer, USA)."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "DNA damage",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00058",
          "quote": "The alkaline comet assay showed that DNA damage was significantly induced by RF-EMFs 4 W/kg for 24 h, but DNA damage was not detected by the neutral comet assay or the expression level of g-H2AX (Fig. 1A and B)."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "Cell viability",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00058",
          "quote": "In addition, cell viability was significantly reduced in the RF-EMFs 4 W/kg group compared with the sham exposure group (Fig. 1C)."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "Autophagy",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00088",
          "quote": "Immunoblot analysis showed that RF-EMFs treatment decreased the level of p62 (Fig. 3A). Evidence of RF-EMFs-induced autophagy was provided by direct observation of the formation of autophagosomes using electron microscopy (Fig. 3B). To further confirm that RF-EMFs induce autophagy in GC-2 cells, these cells were transiently transfected with GFP-LC3 and then treated with RF-EMFs 4 W/kg for 24 h. Fluorescence microscopic examination showed the characteristic punctate fluorescent pattern of GFP-LC3, indicating autophagosome formation and the occurrence of autophagy (Fig. 3C)."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "AMPK/mTOR signaling pathway",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00090",
          "quote": "The results showed that the phosphorylation levels of AMPK significantly increased and p-mTOR significantly decreased after RF-EMFs exposure (Fig. 4A), and pretreatment with melatonin decreased the expression of LC3II/LC3I, and prevented activation of the AMPK/mTOR signaling pathway (Fig. 4B)."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "DNA damage",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00096",
          "quote": "These results indicated that autophagy may protect cells from continuous DNA damage, and inhibition of autophagy could result in accumulation of DNA damage in GC-2 cells."
        }
      ]
    },
    {
      "experiment_id": "b00033",
      "experimental_unit": "GC-2 cells",
      "endpoint_name": "DNA damage",
      "timepoint_unit": "24h",
      "evidence": [
        {
          "block_id": "b00118",
          "quote": "DNA damage was significantly attenuated following overexpression of AMPK a 2 induced by RF-EMFs exposure (Fig. 6B)."
        }
      ]
    }
  ],
